insert into foot_experiments (exp_key, hypothesis, protocol, data_desc, period, model, result, ci_low, ci_high, conclusion, rerun_of, rerun_reason, created_at) values ('c1d3b159d65bbdad7c1f5125', 'Des facteurs de forme, d''enchaînement, de récurrence, d''arbitre ou de confrontations directes apportent de l''information au-delà de la cote', '{"facteurs": 19, "base": "logit(p_m0)", "validation": "moitié chronologique 1 -> 2", "correction": "BH 5 %", "periode": "2022-23 a 2026-27"}', 'football-data 22 ligues, 32250 matchs', '2022-23 a 2026-27', 'logistique', '{"retenus": 0, "meilleur_gain_logloss": 0.00018, "meilleur": "buts marques+encaisses 5 derniers", "p_brut_min": 0.046}', null, null, 'infirmé', null, null, '2026-10-05T17:54:36.572187+00:00') on conflict (exp_key) do nothing;
insert into foot_lessons (error, rule, source_ref, active, created_at) values ('Les séries en cours (+2,5 / -2,5) et l''enchaînement des matchs semblent parlants mais n''ajoutent rien une fois la forme et la cote connues', 'Ne pas sélectionner un match sur une série ou un calendrier chargé ; seules des données que la cote n''a pas (compositions, absences de dernière minute) peuvent encore apporter quelque chose', 'analyse facteurs 05/10', true, '2026-10-05T17:54:36.907161+00:00');
